// EDIT ME: the folder you unpacked Draft Desk into (forward slashes work on Windows too),
// your Telegram chat id (message @userinfobot to get it), and the reply filters.
return [{ json: {
  kit_dir: 'C:/Users/you/draft-desk',
  chat_id: '123456789',
  min_followers: 20000, // accounts outside the watchlist need at least this many followers
  min_velocity: 60, // and their post needs at least this many likes per hour
  max_age_hours: 3, // a reply under an older post earns almost nothing
} }];

// Shared: read the answer file that scripts/ask.js wrote (Extract From File puts it under .data).
function answer(step) {
  const out = $input.first().json.data;
  if (!out) throw new Error(`${step}: answer file was empty`);
  if (!out.ok) throw new Error(`${step}: ${out.error} ${String(out.stderr || out.stdout || out.text || '').slice(0, 400)}`);
  return out;
}

// Drop what the scout should not have sent: bad URLs, replies, small accounts outside the watchlist.
// Then build the free public embed URL that returns the post's real text and like count, so nothing
// the scout claimed reaches the writer unchecked.
const out = answer('scout');
const cfg = $('config').first().json;
const watch = new Set(String(out.attach.watchlist || '').split(/\r?\n/)
  .map((l) => l.replace(/#.*/, '').trim().replace(/^@/, '').toLowerCase()).filter(Boolean));
const items = [];
for (const c of out.data.candidates || []) {
  const m = /x\.com\/([A-Za-z0-9_]+)\/status\/(\d+)/.exec(String(c.tweet_url || ''));
  if (!m || c.is_reply === true) continue;
  const handle = m[1].toLowerCase();
  const inWatchlist = watch.has(handle);
  if (!inWatchlist && (Number(c.author_followers_approx) || 0) < cfg.min_followers) continue;
  const id = m[2];
  // Same token the public embed widget computes for itself.
  const token = ((Number(id) / 1e15) * Math.PI).toString(36).replace(/(0+|\.)/g, '');
  items.push({ json: {
    tweet_url: `https://x.com/${m[1]}/status/${id}`, handle, tweet_id: id, in_watchlist: inWatchlist,
    why_hot: c.why_hot || '',
    verify_url: `https://cdn.syndication.twimg.com/tweet-result?id=${id}&lang=en&token=${token}`,
  } });
}
return items;

// Pair every candidate with its live embed data (same order as the HTTP node's input), keep only
// real top-level posts that are young and climbing, and hand their verbatim text to the writer.
const cfg = $('config').first().json;
const claims = $('dedupe posts').all().map((i) => i.json);
const live = $input.all().map((i) => i.json);
const cands = [];
claims.forEach((claim, i) => {
  const r = live[i] || {};
  if (!r.text || !r.user) return; // deleted, protected or not found
  if (String(r.user.screen_name || '').toLowerCase() !== claim.handle) return;
  if (r.parent || r.in_reply_to_status_id_str || r.in_reply_to_screen_name) return; // a reply after all
  const likes = r.favorite_count || 0;
  const ageHours = r.created_at ? (Date.now() - new Date(r.created_at).getTime()) / 3600000 : null;
  if (ageHours !== null && ageHours > cfg.max_age_hours) return;
  const velocity = ageHours && ageHours > 0.05 ? Math.round(likes / ageHours) : null;
  if (!claim.in_watchlist && velocity !== null && velocity < cfg.min_velocity) return;
  cands.push({
    tweet_url: claim.tweet_url, tweet_id: claim.tweet_id, author: r.user.screen_name,
    in_watchlist: claim.in_watchlist, likes_verified: likes, likes_per_hour: velocity,
    minutes_old: ageHours === null ? null : Math.round(ageHours * 60),
    text_verbatim: String(r.text).slice(0, 600), why_hot: claim.why_hot,
  });
});
if (!cands.length) return []; // quiet half hour: stop here, send nothing
return [{ json: { text: JSON.stringify({ candidates: cands }, null, 1), candidates: cands } }];

// Shared: read the answer file that scripts/ask.js wrote (Extract From File puts it under .data).
function answer(step) {
  const out = $input.first().json.data;
  if (!out) throw new Error(`${step}: answer file was empty`);
  if (!out.ok) throw new Error(`${step}: ${out.error} ${String(out.stderr || out.stdout || out.text || '').slice(0, 400)}`);
  return out;
}

// Shared by the Code nodes that format Telegram messages (inlined by tools/build.js).
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const BANNED = ['delve', 'leverage', 'robust', 'seamless', 'pivotal', 'foster', 'intricate', 'multifaceted',
  'navigate', 'elevate', 'unlock', 'supercharge', 'game-changer', 'revolutionize'];
// Cheap last line of defence: flags what the voice rules ban, so you see it before you post.
function lint(t) {
  const flags = [];
  if (/—/.test(t)) flags.push('em-dash');
  if (/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/u.test(t)) flags.push('emoji');
  if (/(^|\s)#\w/.test(t)) flags.push('hashtag');
  if (t.length > 280) flags.push(`${t.length} chars`);
  for (const w of BANNED) if (new RegExp(`\\b${w}\\b`, 'i').test(t)) flags.push(w);
  return flags;
}
// X web intent: opens the composer with the text filled in. You still press Post yourself.
const intent = (text, replyTo) =>
  'https://x.com/intent/tweet?' + (replyTo ? `in_reply_to=${replyTo}&` : '') + 'text=' + encodeURIComponent(text);

// One Telegram message per reply draft. "Reply on X" opens the X composer as a reply to that post
// with the draft filled in; you read it, fix it, press Reply. Nothing is posted by the pipeline.
const out = answer('reply writer');
const cands = $('assemble candidates').first().json.candidates;
const msgs = [];
for (const r of out.data.replies || []) {
  const target = String(r.target_url || '');
  const c = cands.find((x) => x.tweet_url === target || target.endsWith(`/status/${x.tweet_id}`));
  if (!c || !r.text) continue; // never deliver a reply to a post we did not verify
  const flags = lint(r.text);
  let t = `#reply <b>@${esc(c.author)}</b>`;
  t += c.likes_per_hour ? ` · ${c.likes_per_hour} likes/h` : ` · ${c.likes_verified} likes`;
  if (c.minutes_old !== null) t += ` · ${c.minutes_old} min old`;
  t += `\n<i>${esc(c.text_verbatim.slice(0, 200))}</i>`;
  t += `\n\n<blockquote>${esc(r.text)}</blockquote>`;
  t += `\n${esc(r.type || '')}${r.why ? ': ' + esc(r.why) : ''}`;
  if (flags.length) t += `\nlint: ${esc(flags.join(', '))}`;
  msgs.push({ json: { text: t.slice(0, 3900), reply_url: intent(r.text, c.tweet_id), post_url: c.tweet_url } });
}
return msgs;
